// Generates src/styles/tokens.css (Tailwind v4 @theme) from @blurt/shared/theme.
// Run: pnpm gen:tokens. `--check` fails if the committed file is stale (used by lint/CI).
import { readFileSync, writeFileSync } from 'node:fs';
import { colors, elevation, radius, space, surfaces, webFontFamilies } from '@blurt/shared/theme';

const out = new URL('../src/styles/tokens.css', import.meta.url);
const kebab = (s) => s.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`);

const lines = [
  '/* GENERATED by scripts/gen-tokens.mjs from @blurt/shared/theme. Do not edit by hand. */',
  '@theme {',
  "  /* Only brand colours exist: Tailwind's default palette is removed (AGENTS.md rule 1). */",
  '  --color-*: initial;',
  '  --color-transparent: transparent;',
  '  --color-current: currentColor;',
  ...Object.entries(colors).map(([k, v]) => `  --color-${kebab(k)}: ${v};`),
  ...Object.entries(radius).map(([k, v]) => `  --radius-${kebab(k)}: ${v}px;`),
  ...Object.entries(space)
    .filter(([k]) => k !== 'screen')
    .map(([k, v]) => `  --spacing-${k}: ${v}px;`),
  `  --shadow-card: 0 ${elevation.card.offsetY}px ${elevation.card.blur}px ${surfaces.cardShadow};`,
  `  --font-display: var(--font-bricolage), ${webFontFamilies.display};`,
  `  --font-sans: var(--font-dm-sans), ${webFontFamilies.body};`,
  '}',
  '',
];
const css = lines.join('\n');

if (process.argv.includes('--check')) {
  let current = '';
  try {
    current = readFileSync(out, 'utf8');
  } catch {}
  if (current !== css) {
    console.error('src/styles/tokens.css is out of date. Run: pnpm --filter dashboard gen:tokens');
    process.exit(1);
  }
} else {
  writeFileSync(out, css);
  console.log('Wrote src/styles/tokens.css');
}
